import json
import sys

data = json.load(sys.stdin)

# Search for Federal Intermediate Credit Bank debentures data
def find_ficc_debentures(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'intermediate' in key.lower() or 'credit' in key.lower() or 'debenture' in key.lower():
                results.append((path + '.' + key if path else key, value))
            results.extend(find_ficc_debentures(value, path + '.' + key if path else key))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_ficc_debentures(item, f'{path}[{i}]'))
    return results

results = find_ficc_debentures(data)
for r in results:
    print(f'{r[0]}: {str(r[1])[:200]}')
