import json
import sys

data = json.load(sys.stdin)

# Search for tables related to Federal Intermediate Credit Banks
def search_keys(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(key, str):
                results.append(key)
            results.extend(search_keys(value, path + '.' + key if path else key))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_keys(item, f'{path}[{i}]'))
    return results

